cypress_script:
describe('Checkbox Form Functionality', () => {
  it('should allow the user to check and uncheck checkboxes', () => {
    cy.visit('https://the-internet.herokuapp.com/checkboxes');
    cy.get('input[type="checkbox"]').first().check();
    cy.get('input[type="checkbox"]').first().should('be.checked');
    cy.get('input[type="checkbox"]').first().uncheck();
    cy.get('input[type="checkbox"]').first().should('not.be.checked');
  });

  it('should not change the URL when no checkboxes are checked', () => {
    cy.visit('https://the-internet.herokuapp.com/checkboxes');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/checkboxes');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Checkbox Form Functionality', () => {
  test('should allow the user to check and uncheck checkboxes', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/checkboxes');
    const checkbox1 = page.locator('input[type="checkbox"]').nth(0);
    await checkbox1.check();
    await expect(checkbox1).toBeChecked();
    await checkbox1.uncheck();
    await expect(checkbox1).not.toBeChecked();
  });

  test('should not change the URL when no checkboxes are checked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/checkboxes');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/checkboxes');
  });
});
